            bool ppu = g_cfg.core.ppu_prof.get(), spu = g_cfg.core.spu_prof.get(), debug = g_cfg.core.spu_debug.get();
            thread_scheduler_mode scheduler = g_cfg.core.thread_scheduler.get();
