        using namespace ppu_instructions;
        using namespace ppu_instructions::implicts;
        const std::array<u32, 7> opcodes{LI(3, 0), MTCTR(4), ADDI(3, 3, 1), BC(16, 0, -4),
            STW(3, 6, 0), LWZ(7, 6, 0), ORI(7, 8, 0x100)};
