extern "C" __attribute__((visibility("default"))) int armsx3_core_test_semaphore_fifo_surplus()
{
    ARMSX3StartupLog("P80 BEFORE FIFO semaphore posted wake with surplus and signed count boundaries");
    const int result = armsx3_core_test_semaphore_surplus_batch(SYS_SYNC_FIFO);
    if (!result) ARMSX3StartupLog("P80 PASS: FIFO post2 wakes one waiter and retains one spare permit; signed count boundaries and cleanup PASS");
    return result;
}

extern "C" __attribute__((visibility("default"))) int armsx3_core_test_semaphore_priority_surplus()
{
    ARMSX3StartupLog("P81 BEFORE priority semaphore posted wake with surplus and signed count boundaries");
    const int result = armsx3_core_test_semaphore_surplus_batch(SYS_SYNC_PRIORITY);
    if (!result) ARMSX3StartupLog("P81 PASS: native priority protocol single-waiter post2 wake/spare permit/count boundaries/cleanup PASS; multiwaiter ordering untested");
    return result;
}

